import React, { useEffect, useState } from "react";
import { useForm, FormProvider } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  Button,
  FormTextField,
  FormTextArea,
  FormSelect,
  FormSwitch,
  FormImagePicker,
} from "@flaner/ui-components";
import { createGroupSchema, type CreateGroupSchema } from "../utils/schemas/groups";
import { useCreateGroupMutation } from "../hooks";
import { uploadToCloudinary, toast, compressImage, ONE_MB } from "@flaner/shared";
import { useCommunityTranslations } from "../hooks/useCommunityTranslations";

export interface CreateGroupModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CreateGroupModal({ open, onOpenChange }: CreateGroupModalProps) {
  const { t } = useCommunityTranslations();
  const { mutateAsync: createGroup, isPending: isCreating } = useCreateGroupMutation();
  const [isUploading, setIsUploading] = useState(false);
  const isPending = isCreating || isUploading;

  const methods = useForm<CreateGroupSchema>({
    resolver: zodResolver(createGroupSchema),
    defaultValues: {
      name: "",
      description: "",
      type: "private",
      requiresApproval: false,
      avatarUrl: "",
    },
  });

  const { handleSubmit, watch, reset, control } = methods;
  const groupType = watch("type");

  useEffect(() => {
    if (open) {
      reset({
        name: "",
        description: "",
        type: "private",
        requiresApproval: false,
        avatarUrl: "",
      });
    }
  }, [open, reset]);

  const onSubmit = async (data: CreateGroupSchema) => {
    try {
      setIsUploading(true);
      let finalAvatarUrl: string | null = null;
      
      if (data.avatarUrl instanceof File) {
        const compressed = await compressImage(data.avatarUrl, ONE_MB);
        finalAvatarUrl = await uploadToCloudinary(compressed);
      } else if (typeof data.avatarUrl === "string" && data.avatarUrl) {
        finalAvatarUrl = data.avatarUrl;
      }
      
      const payload = {
        ...data,
        description: data.description || "",
        avatarUrl: finalAvatarUrl,
      };

      await createGroup(payload);
      onOpenChange(false);
    } catch (error) {
      console.error("Failed to create group", error);
      toast.failure(t("groupsView.createModal.error"));
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{t("groupsView.createModal.title")}</DialogTitle>
        </DialogHeader>

        <FormProvider {...methods}>
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 py-4">
            <FormImagePicker
              control={control as any}
              name="avatarUrl"
              label={t("groupsView.createModal.avatarLabel")}
              disabled={isPending}
              maxSize={ONE_MB}
            />

            <FormTextField
              control={control as any}
              name="name"
              label={t("groupsView.createModal.nameLabel")}
              placeholder={t("groupsView.createModal.namePlaceholder")}
              disabled={isPending}
            />

            <FormTextArea
              control={control as any}
              name="description"
              label={t("groupsView.createModal.descLabel")}
              placeholder={t("groupsView.createModal.descPlaceholder")}
              disabled={isPending}
              rows={3}
            />

            <FormSelect
              control={control as any}
              name="type"
              label={t("groupsView.createModal.typeLabel")}
              options={[
                { label: t("groupsView.createModal.typePrivate"), value: "private" },
                { label: t("groupsView.createModal.typePublic"), value: "public" },
              ]}
              disabled={isPending}
            />

            {groupType === "public" && (
              <FormSwitch
                control={control as any}
                name="requiresApproval"
                label={t("groupsView.createModal.requiresApprovalLabel")}
                description={t("groupsView.createModal.requiresApprovalDesc")}
                disabled={isPending}
              />
            )}

            <div className="flex justify-end gap-3 pt-4">
              <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={isPending}>
                {t("groupsView.createModal.cancel")}
              </Button>
              <Button type="submit" isBusy={isPending}>
                {t("groupsView.createModal.submit")}
              </Button>
            </div>
          </form>
        </FormProvider>
      </DialogContent>
    </Dialog>
  );
}

export default CreateGroupModal;

import React, { useState } from "react";
import { 
  Button, 
  Sheet, 
  SheetContent, 
  SheetHeader, 
  SheetTitle, 
  SheetDescription, 
  SheetTrigger,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  ConfirmationPopup,
  Avatar,
  AvatarImage,
  AvatarFallback
} from "@flaner/ui-components";
import { Settings, MoreVertical, ShieldAlert, ShieldCheck, Shield, UserMinus, Crown, Trash2 } from "lucide-react";
import { useAuth } from "@flaner/shared";
import { useNavigate } from "react-router";
import { toast } from "sonner";
import { useDeleteGroupMutation, useGetGroupMembersQuery, useGetUsersQuery, useRemoveGroupMemberMutation, useTransferGroupOwnershipMutation, useUpdateGroupMemberRoleMutation } from "../../hooks";
import { useCommunityTranslations } from "../../hooks/useCommunityTranslations";
import type { GroupRole, GroupMember } from "../../api/types";

interface ManageGroupSheetProps {
  groupId: string;
}

export function ManageGroupSheet({ groupId }: ManageGroupSheetProps) {
  const { t } = useCommunityTranslations();
  const { user } = useAuth();
  
  const { data: members = [], isLoading: membersLoading } = useGetGroupMembersQuery(groupId);
  const memberUserIds = members.map(m => m.userId);
  const { data: membersProfiles, isLoading: profilesLoading } = useGetUsersQuery(memberUserIds);

  const navigate = useNavigate();
  const updateRoleMutation = useUpdateGroupMemberRoleMutation();
  const transferOwnershipMutation = useTransferGroupOwnershipMutation();
  const removeMemberMutation = useRemoveGroupMemberMutation();
  const deleteGroupMutation = useDeleteGroupMutation();

  const [confirmTransferUserId, setConfirmTransferUserId] = useState<string | null>(null);
  const [confirmRemoveUserId, setConfirmRemoveUserId] = useState<string | null>(null);
  const [isDeleteConfirmOpen, setIsDeleteConfirmOpen] = useState(false);

  const currentUserRole = members.find(m => m.userId === user?.uid)?.role;

  // Helpers
  const ROLE_PRIORITY: Record<GroupRole, number> = {
    owner: 4,
    admin: 3,
    moderator: 2,
    member: 1,
  };

  const currentPriority = currentUserRole ? ROLE_PRIORITY[currentUserRole] : 0;

  const canManageMember = (targetRole: GroupRole) => {
    if (!currentUserRole) return false;
    return currentPriority > ROLE_PRIORITY[targetRole];
  };

  const getRoleOption = (targetMember: GroupMember, roleToAssign: GroupRole) => {
    const isPromotion = ROLE_PRIORITY[roleToAssign] > ROLE_PRIORITY[targetMember.role];

    if (roleToAssign === "admin") {
      return {
        label: t("manageGroupSheet.promoteToAdmin"),
        icon: <ShieldCheck className="size-4 mr-2 text-blue-500" />,
      };
    }

    if (roleToAssign === "moderator") {
      return {
        label: isPromotion ? t("manageGroupSheet.promoteToModerator") : t("manageGroupSheet.demoteToModerator"),
        icon: <ShieldAlert className="size-4 mr-2 text-orange-500" />,
      };
    }

    if (roleToAssign === "member") {
      return {
        label: t("manageGroupSheet.demoteToMember"),
        icon: <Shield className="size-4 mr-2 text-muted-foreground" />,
      };
    }

    return null;
  };

  const handleUpdateRole = async (targetUserId: string, newRole: GroupRole) => {
    try {
      await updateRoleMutation.mutateAsync({ groupId, userId: targetUserId, role: newRole });
      toast.success(t("manageGroupSheet.roleUpdateSuccess"));
    } catch (err: any) {
      if (err.message?.includes('permission-denied')) {
        toast.error(t("manageGroupSheet.permissionDenied"));
      } else {
        toast.error(t("manageGroupSheet.roleUpdateError"));
      }
    }
  };

  const handleTransferOwnership = async () => {
    if (!user || !confirmTransferUserId) return;
    try {
      await transferOwnershipMutation.mutateAsync({ 
        groupId, 
        currentOwnerId: user.uid, 
        newOwnerId: confirmTransferUserId 
      });
      setConfirmTransferUserId(null);
      toast.success(t("manageGroupSheet.transferSuccess"));
    } catch (err: any) {
      if (err.message?.includes('permission-denied')) {
        toast.error(t("manageGroupSheet.permissionDenied"));
      } else {
        toast.error(t("manageGroupSheet.transferError"));
      }
    }
  };

  const handleRemoveMember = async () => {
    if (!confirmRemoveUserId) return;
    try {
      await removeMemberMutation.mutateAsync({ groupId, userId: confirmRemoveUserId });
      setConfirmRemoveUserId(null);
      toast.success(t("manageGroupSheet.removeSuccess"));
    } catch (err: any) {
      if (err.message?.includes('permission-denied')) {
        toast.error(t("manageGroupSheet.permissionDenied"));
      } else {
        toast.error(t("manageGroupSheet.removeError"));
      }
    }
  };

  const handleDeleteGroup = async () => {
    try {
      await deleteGroupMutation.mutateAsync(groupId);
      setIsDeleteConfirmOpen(false);
      toast.success(t("manageGroupSheet.deleteSuccess"));
      navigate("/community/groups");
    } catch (err: any) {
      if (err.message?.includes('permission-denied')) {
        toast.error(t("manageGroupSheet.permissionDenied"));
      } else {
        toast.error(t("manageGroupSheet.deleteError"));
      }
    }
  };

  const getRoleIcon = (role: GroupRole) => {
    switch (role) {
      case 'owner': return <Crown className="size-4 text-yellow-500" />;
      case 'admin': return <ShieldCheck className="size-4 text-blue-500" />;
      case 'moderator': return <ShieldAlert className="size-4 text-orange-500" />;
      default: return <Shield className="size-4 text-muted-foreground" />;
    }
  };

  const getRoleTranslation = (role: GroupRole) => {
    return t(`manageGroupSheet.role_${role}`) || role;
  };

  return (
    <>
      <Sheet>
        <SheetTrigger asChild>
          <Button variant="primary" className="rounded-xl flex-1 md:flex-none">
            <Settings className="size-4" />
            {t("groupDetails.manageBtn")}
          </Button>
        </SheetTrigger>
        <SheetContent className="w-full sm:max-w-md p-6 bg-card/95 backdrop-blur-md border-l border-border flex flex-col h-full shadow-2xl">
          <SheetHeader className="p-0 border-b border-border pb-4">
            <SheetTitle className="text-xl font-bold font-heading">{t("manageGroupSheet.title")}</SheetTitle>
            <SheetDescription className="text-xs text-muted-foreground mt-1">
              {t("manageGroupSheet.desc")}
            </SheetDescription>
          </SheetHeader>

          <div className="flex-1 overflow-y-auto space-y-4 py-4 pr-1 scrollbar-none">
            {membersLoading || profilesLoading ? (
              <div className="flex justify-center py-4">
                <div className="text-center text-muted-foreground">{t("groupDetails.loading")}</div>
              </div>
            ) : (
              <div className="space-y-2">
                {members.map((member: GroupMember) => {
                  const profile = membersProfiles?.find(p => p.uid === member.userId);
                  const displayName = profile?.username || member.userId;
                  const initials = displayName.substring(0, 2).toUpperCase();
                  
                  const canManage = canManageMember(member.role) && member.userId !== user?.uid;

                  return (
                    <div key={member.userId} className="flex items-center justify-between p-3 rounded-xl hover:bg-muted/30 transition-colors border border-transparent hover:border-border/50">
                      <div className="flex items-center gap-3">
                        <Avatar className="size-10 border border-border">
                          {profile?.avatarUrl && <AvatarImage src={profile.avatarUrl} alt={displayName} />}
                          <AvatarFallback className="bg-gradient-to-tr from-brand to-brand-dark text-zinc-950 font-bold text-sm">
                            {initials}
                          </AvatarFallback>
                        </Avatar>
                        <div>
                          <div className="font-medium text-sm flex items-center gap-1.5">
                            {displayName}
                            {member.userId === user?.uid && (
                              <span className="text-[10px] text-muted-foreground bg-muted px-1.5 py-0.5 rounded-sm ml-1">(Ty)</span>
                            )}
                          </div>
                          <div className="text-xs text-muted-foreground flex items-center gap-1 mt-0.5">
                            {getRoleIcon(member.role)}
                            {getRoleTranslation(member.role)}
                          </div>
                        </div>
                      </div>

                      {canManage && (
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon" className="size-8 rounded-full">
                              <MoreVertical className="size-4 text-muted-foreground" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-48">
                            {(["admin", "moderator", "member"] as GroupRole[]).map((roleToAssign) => {
                              if (currentPriority <= ROLE_PRIORITY[roleToAssign] || roleToAssign === member.role) {
                                return null;
                              }
                              const option = getRoleOption(member, roleToAssign);
                              if (!option) return null;

                              return (
                                <DropdownMenuItem key={roleToAssign} onClick={() => handleUpdateRole(member.userId, roleToAssign)}>
                                  {option.icon}
                                  {option.label}
                                </DropdownMenuItem>
                              );
                            })}

                            {currentUserRole === 'owner' && (
                              <DropdownMenuItem 
                                className="text-yellow-600 focus:text-yellow-700" 
                                onClick={() => setConfirmTransferUserId(member.userId)}
                              >
                                <Crown className="size-4 mr-2" />
                                {t("manageGroupSheet.transferOwnership")}
                              </DropdownMenuItem>
                            )}

                            <DropdownMenuItem 
                              className="text-destructive focus:text-destructive"
                              onClick={() => setConfirmRemoveUserId(member.userId)}
                            >
                              <UserMinus className="size-4 mr-2" />
                              {t("manageGroupSheet.removeMember")}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {currentUserRole === "owner" && (
              <div className="pt-4 border-t border-border mt-4">
                <h4 className="text-xs font-semibold uppercase tracking-wider text-destructive mb-2">
                  {t("manageGroupSheet.dangerZoneTitle")}
                </h4>
                <Button
                  variant="outline"
                  isBusy={deleteGroupMutation.isPending}
                  className="w-full text-destructive border-destructive/30 hover:bg-destructive hover:text-white rounded-xl flex items-center justify-center gap-2"
                  onClick={() => setIsDeleteConfirmOpen(true)}
                >
                  <Trash2 className="size-4" />
                  {t("manageGroupSheet.deleteGroupBtn")}
                </Button>
              </div>
            )}
          </div>
        </SheetContent>
      </Sheet>

      <ConfirmationPopup
        open={!!confirmTransferUserId}
        onOpenChange={(isOpen) => !isOpen && setConfirmTransferUserId(null)}
        title={t("manageGroupSheet.transferConfirmTitle")}
        description={t("manageGroupSheet.transferConfirmDesc")}
        confirmLabel={t("manageGroupSheet.transferConfirmBtn")}
        cancelLabel={t("groupDetails.cancelBtn")}
        variant="destructive"
        isConfirming={transferOwnershipMutation.isPending}
        onConfirm={handleTransferOwnership}
      />

      <ConfirmationPopup
        open={!!confirmRemoveUserId}
        onOpenChange={(isOpen) => !isOpen && setConfirmRemoveUserId(null)}
        title={t("manageGroupSheet.removeConfirmTitle")}
        description={t("manageGroupSheet.removeConfirmDesc")}
        confirmLabel={t("manageGroupSheet.removeConfirmBtn")}
        cancelLabel={t("groupDetails.cancelBtn")}
        variant="destructive"
        isConfirming={removeMemberMutation.isPending}
        onConfirm={handleRemoveMember}
      />

      <ConfirmationPopup
        open={isDeleteConfirmOpen}
        onOpenChange={setIsDeleteConfirmOpen}
        title={t("manageGroupSheet.deleteConfirmTitle")}
        description={t("manageGroupSheet.deleteConfirmDesc")}
        confirmLabel={t("manageGroupSheet.deleteConfirmBtn")}
        cancelLabel={t("groupDetails.cancelBtn")}
        variant="destructive"
        isConfirming={deleteGroupMutation.isPending}
        onConfirm={handleDeleteGroup}
      />
    </>
  );
}

import { useInfiniteQuery, type UseInfiniteQueryOptions, useQueryClient, keepPreviousData } from "@tanstack/react-query";
import type { DocumentData, QueryDocumentSnapshot } from "firebase/firestore";
import { searchGlobalGroups } from "../../../api/groups";

const getSearchGlobalGroupsQueryKeys = (searchQuery: string) => ["searchGlobalGroups", searchQuery];

export const useSearchGlobalGroupsQuery = (
  searchQuery: string,
  pageSize: number = 10,
  options?: Omit<
    UseInfiniteQueryOptions<any, any, any, any, any>,
    "queryKey" | "queryFn" | "getNextPageParam" | "initialPageParam" | "placeholderData"
  >,
) => {
  return useInfiniteQuery({
    queryKey: getSearchGlobalGroupsQueryKeys(searchQuery),
    queryFn: ({ pageParam }) => {
      if (!searchQuery.trim()) return { groups: [], nextCursor: undefined };
      return searchGlobalGroups(searchQuery, pageSize, pageParam);
    },
    initialPageParam: undefined as QueryDocumentSnapshot<DocumentData, DocumentData> | undefined,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
    enabled: !!searchQuery.trim(),
    staleTime: 5000,
    placeholderData: keepPreviousData,
    ...options,
  });
};

export const useInvalidateSearchGlobalGroupsQuery = () => {
  const queryClient = useQueryClient();
  return () => queryClient.invalidateQueries({ queryKey: ["searchGlobalGroups"] });
};

export default useSearchGlobalGroupsQuery;

import { useDebounce } from "@flaner/shared";
import { Button, GroupSearchResultItem, IconTextField, SearchBar } from "@flaner/ui-components";
import { Filter, Plus, Search, Users } from "lucide-react";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router";
import { toast } from "sonner";
import type { Group } from "../../api/types";
import { CreateGroupModal } from "../../components/CreateGroupModal";
import { GroupCard } from "../../components/groups/GroupCard";
import { useGetUserGroupsQuery, useSearchGlobalGroupsQuery } from "../../hooks";
import { useCommunityTranslations } from "../../hooks/useCommunityTranslations";
import { GroupInvitationsSheet } from "../../components/groups/GroupInvitationsSheet";

export function GroupsListView() {
  const { t } = useCommunityTranslations();
  const navigate = useNavigate();

  // User's own groups
  const { data: myGroups = [], isLoading: isLoadingMyGroups } = useGetUserGroupsQuery();

  // Search state for global groups
  const [searchQuery, setSearchQuery] = useState("");
  const debouncedSearch = useDebounce(searchQuery, 300);

  // Search state for user's own groups
  const [myGroupsSearchQuery, setMyGroupsSearchQuery] = useState("");

  const {
    data: searchData,
    isFetching,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    error: searchError,
  } = useSearchGlobalGroupsQuery(debouncedSearch);

  useEffect(() => {
    if (searchError) {
      console.error("Search error:", searchError);
      toast.error(`Błąd wyszukiwania: ${(searchError as any).message}`);
    }
  }, [searchError]);

  const globalGroups = (searchData?.pages.flatMap((page: any) => page.groups) || []) as Group[];

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  const filteredMyGroups = myGroups.filter((g) => g.name.toLowerCase().includes(myGroupsSearchQuery.toLowerCase()));

  const handleGroupSelect = async (group: Group) => {
    navigate(`/community/groups/${group.id}`);
  };

  return (
    <div className="max-w-5xl mx-auto py-6 space-y-8 px-4 md:px-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-brand/10 text-brand rounded-xl">
            <Users className="size-6" />
          </div>
          <div>
            <h1 className="text-3xl font-black tracking-tight text-foreground font-heading">{t("groupsView.title")}</h1>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <IconTextField
            icon={<Filter className="size-4" />}
            size="lg"
            value={myGroupsSearchQuery}
            onChange={(e) => setMyGroupsSearchQuery(e.target.value)}
            placeholder={t("groupsView.filterPlaceholder")}
            isClearable
            onClear={() => setMyGroupsSearchQuery("")}
          />
          <SearchBar
            icon={<Search className="size-4" />}
            size="lg"
            value={searchQuery}
            onChange={(val) => setSearchQuery(val)}
            placeholder={t("groupsView.searchPlaceholder")}
            isClearable
            onClear={() => setSearchQuery("")}
            onClose={() => setSearchQuery("")}
            results={globalGroups}
            isLoading={isFetching && !isFetchingNextPage}
            hasMore={hasNextPage}
            onShowMore={() => fetchNextPage()}
            isFetchingNextPage={isFetchingNextPage}
            renderResult={(group) => (
              <GroupSearchResultItem
                avatarUrl={group.avatarUrl}
                name={group.name}
                requiresApproval={group.requiresApproval}
              />
            )}
            onSelect={handleGroupSelect}
            alwaysOpen={false}
          />
          <GroupInvitationsSheet />
          <Button size="lg" onClick={() => setIsCreateModalOpen(true)}>
            <Plus className="size-4" />
            {t("groupsView.createBtn")}
          </Button>
        </div>
      </div>

      {isLoadingMyGroups ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="h-32 bg-muted/30 animate-pulse rounded-2xl border border-border/50" />
          ))}
        </div>
      ) : filteredMyGroups.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredMyGroups.map((group) => (
            <GroupCard key={group.id} group={group} />
          ))}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-20 text-center border border-dashed border-border/50 rounded-3xl bg-muted/10">
          <div className="size-16 bg-muted rounded-full flex items-center justify-center mb-4">
            <Users className="size-8 text-muted-foreground" />
          </div>
          <h3 className="text-xl font-semibold mb-2">{t("groupsView.emptyState.title")}</h3>
          <p className="text-muted-foreground max-w-sm mb-6">{t("groupsView.emptyState.desc")}</p>
          <Button variant="outline" className="rounded-xl" onClick={() => setIsCreateModalOpen(true)}>
            {t("groupsView.emptyState.actionBtn")}
          </Button>
        </div>
      )}

      <CreateGroupModal open={isCreateModalOpen} onOpenChange={setIsCreateModalOpen} />
    </div>
  );
}

