import { type MfeName } from "@flaner/shared";
import { LoadingFallback } from "@flaner/ui-components";
import { loadRemote } from "@module-federation/runtime";
import * as Lucide from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate, type RouteObject } from "react-router";

export type PageTilesViewProps = {
  mfe: MfeName;
};

// Module-level cache to prevent flashing loading spinners when routes are already loaded
const routesCache = new Map<string, RouteObject[]>();

export function PageTilesView({ mfe }: PageTilesViewProps) {
  const navigate = useNavigate();
  const { t } = useTranslation();

  const cached = routesCache.get(mfe);
  const [routes, setRoutes] = useState<RouteObject[]>(cached || []);
  const [loading, setLoading] = useState(!cached);

  useEffect(() => {
    let active = true;

    if (!routesCache.has(mfe)) {
       
      setLoading(true);
    }

    loadRemote<{ routes: RouteObject[] }>(`${mfe}/routes`)
      .then((mod) => {
        const loadedRoutes = mod?.routes || [];
        routesCache.set(mfe, loadedRoutes);
        if (active) {
          setRoutes(loadedRoutes);
          setLoading(false);
        }
      })
      .catch((err) => {
        const isNotExposed =
          err?.message?.includes("Module ./routes does not exist") || err?.message?.includes("Failed to get expose");

        if (isNotExposed) {
          console.warn(
            `[PageTilesView] MFE "${mfe}" does not expose './routes' yet. This is expected if the MFE has no sub-views.`
          );
        } else {
          console.error(`[PageTilesView] Failed to load routes for MFE: ${mfe}`, err);
        }

        if (active) {
          setRoutes([]);
          setLoading(false);
        }
      });

    return () => {
      active = false;
    };
  }, [mfe]);

  if (loading) {
    return <LoadingFallback />;
  }

  // Helper to extract displayable tile routes recursively
  const getTileRoutes = (items: RouteObject[]): RouteObject[] => {
    const tilesList: RouteObject[] = [];
    for (const route of items) {
      const handle = route.handle as { label?: string; hideInNav?: boolean } | undefined;
      if (route.path && handle?.label && !handle.hideInNav) {
        tilesList.push(route);
      }
      if (route.children && route.children.length > 0) {
        tilesList.push(...getTileRoutes(route.children));
      }
    }
    return tilesList;
  };

  const tiles = getTileRoutes(routes);

  return (
    <div className="max-w-6xl mx-auto py-6 space-y-6">
      <div className="flex items-center gap-3 px-6">
        <h1 className="text-3xl font-black tracking-tight text-foreground font-heading">{t(`nav.${mfe}`)}</h1>
      </div>

      {tiles.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center max-w-md mx-auto my-12 animate-in fade-in duration-300">
          <div className="w-12 h-12 rounded-full bg-zinc-800 flex items-center justify-center text-muted-foreground mb-4 font-bold text-xl">
            ?
          </div>
          <h2 className="text-zinc-300 font-semibold mb-2">{t("mfe.noViewsTitle")}</h2>
          <p className="text-zinc-500 text-sm">{t("mfe.noViewsDesc")}</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6 p-6 animate-in fade-in duration-200">
          {tiles.map((route, index) => {
            const handle = route.handle as { label: string; icon?: string };
            const IconComponent = handle.icon ? (Lucide as any)[handle.icon] : null;

            const labelKey = handle.label;
            const labelText = t(labelKey, {
              defaultValue: t(`${mfe}.${labelKey}`, { defaultValue: labelKey }),
            });

            return (
              <div
                key={route.path || index}
                onClick={() => navigate(`/${mfe}/${route.path!}`)}
                className="flex flex-col items-center justify-center p-8 bg-zinc-900/50 hover:bg-zinc-800/40 border border-border/50 hover:border-brand/40 rounded-2xl cursor-pointer transition-all duration-300 group hover:-translate-y-1 shadow-sm hover:shadow-md hover:shadow-brand/5"
              >
                {IconComponent ? (
                  <div className="p-4 bg-brand/10 text-brand group-hover:bg-brand/20 group-hover:scale-110 rounded-2xl mb-4 transition-all duration-300">
                    <IconComponent className="size-8" />
                  </div>
                ) : (
                  <div className="p-4 bg-zinc-800 text-muted-foreground rounded-2xl mb-4" />
                )}
                <h3 className="font-semibold text-lg text-foreground group-hover:text-brand transition-colors duration-300">
                  {labelText}
                </h3>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default PageTilesView;

import { clientsClaim, skipWaiting } from "workbox-core";
import { ExpirationPlugin } from "workbox-expiration";
import { cleanupOutdatedCaches, matchPrecache, precacheAndRoute } from "workbox-precaching";
import { NavigationRoute, registerRoute, setCatchHandler } from "workbox-routing";
import { NetworkFirst, StaleWhileRevalidate } from "workbox-strategies";

declare let self: any;

// Take control immediately
skipWaiting();
clientsClaim();

// Precache all assets generated by the build (injected by vite-plugin-pwa)
cleanupOutdatedCaches();
precacheAndRoute(self.__WB_MANIFEST);

// ──────────────────────────────────────────────
// Runtime caching strategies
// ──────────────────────────────────────────────

// 1. Translation files — StaleWhileRevalidate
// Serve cached translations instantly, update in the background
registerRoute(
  ({ url }) => url.pathname.includes("/locales/"),
  new StaleWhileRevalidate({
    cacheName: "translations-cache",
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
      }),
    ],
  })
);

// 2. Microfrontend Manifests (remoteEntry.js) — NetworkFirst
// Always query network first so we get redeployed MFEs, fallback to cache
registerRoute(
  ({ url }) => url.pathname.endsWith("/remoteEntry.js") || url.pathname.endsWith("/remoteEntry.ssr.js"),
  new NetworkFirst({
    cacheName: "mfe-entries-cache",
    networkTimeoutSeconds: 2,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 60 * 60 * 24, // 1 day
      }),
    ],
  })
);

// 3. Hashed assets and MFE chunk files — StaleWhileRevalidate
// Cache remote JS/CSS assets dynamically
registerRoute(
  ({ url }) => url.pathname.includes("/assets/"),
  new StaleWhileRevalidate({
    cacheName: "mfe-assets-cache",
    plugins: [
      new ExpirationPlugin({
        maxEntries: 150,
        maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
      }),
    ],
  })
);

// 4. Navigation requests — NetworkFirst with offline fallback
const navigationHandler = new NetworkFirst({
  cacheName: "navigation-cache",
  networkTimeoutSeconds: 3,
});

const navigationRoute = new NavigationRoute(navigationHandler, {
  // Don't handle Firebase auth redirect URLs
  denylist: [/\/__\/auth\//],
});

registerRoute(navigationRoute);

// 5. Offline fallback
setCatchHandler(async ({ request }) => {
  if (request.mode === "navigate") {
    return (await matchPrecache("offline.html")) || (await matchPrecache("/offline.html")) || Response.error();
  }
  return Response.error();
});

import { useAuth } from "@flaner/shared";
import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateUserProfile, type UpdateProfilePayload } from "../../../api";

export const useUpdateSettingsMutation = (options?: UseMutationOptions<void, Error, UpdateProfilePayload>) => {
  const { user, updateUser } = useAuth();

  return useMutation<void, Error, UpdateProfilePayload>({
    mutationFn: async (payload) => {
      if (!user) {
        throw new Error("User must be authenticated to update settings");
      }
      await updateUserProfile(user.uid, payload);
    },
    ...options,
    onSuccess: async (data, variables, context) => {
      // Sync local context state
      updateUser(variables);

      // Call parent onSuccess if provided
      if (options?.onSuccess) {
        await (options.onSuccess as any)(data, variables, context);
      }
    },
  });
};
export default useUpdateSettingsMutation;

import { compressImage, toast, uploadToCloudinary, useAuth, ONE_MB } from "@flaner/shared";
import { Button, FormImagePicker, FormSelect, FormSwitch, FormTextField, Separator } from "@flaner/ui-components";
import { zodResolver } from "@hookform/resolvers/zod";
import { useEffect } from "react";
import { FormProvider, useForm } from "react-hook-form";
import { useSettingsTranslations } from "../hooks/useSettingsTranslations";
import { useUpdateSettingsMutation } from "../hooks";
import getSettingsSchema from "../utils/schemas/settings-schema";

export function SettingsView() {
  const { user } = useAuth();
  const { t, i18n } = useSettingsTranslations();
  const mutation = useUpdateSettingsMutation();

  const settingsForm = useForm({
    resolver: zodResolver(getSettingsSchema(t)),
    defaultValues: {
      username: user?.username || "",
      language: user?.language || "pl",
      darkMode: user?.darkMode ?? true,
      avatar: user?.avatarUrl || null,
    },
  });

  const {
    handleSubmit,
    reset,
    formState: { isDirty },
  } = settingsForm;

  // Keep form in sync if auth user details load later
  useEffect(() => {
    if (user) {
      reset({
        username: user.username,
        language: user.language,
        darkMode: user.darkMode,
        avatar: user.avatarUrl || null,
      });
    }
  }, [user, reset]);

  const onSubmit = async (data: any) => {
    let avatarUrl = user?.avatarUrl || "";

    if (data.avatar instanceof File) {
      try {
        // Compress avatar (max 1MB)
        const compressed = await compressImage(data.avatar, ONE_MB);
        // Upload to Cloudinary
        avatarUrl = await uploadToCloudinary(compressed);
      } catch (err: any) {
        console.error(err);
        toast.failure(err?.message || t("notifications.avatarError"));
        return;
      }
    } else if (data.avatar === null) {
      avatarUrl = "";
    }

    const payload = {
      username: data.username,
      language: data.language,
      darkMode: data.darkMode,
      avatarUrl,
    };

    mutation.mutate(payload, {
      onSuccess: () => {
        // Sync global app translation language immediately
        i18n.changeLanguage(data.language);
        toast.success(t("notifications.success"));
