import { useController, UseControllerProps } from "react-hook-form";
import { Select, CustomSelectProps } from "./Select";

export type FormSelectProps = Omit<CustomSelectProps, "name" | "value" | "onChange" | "onBlur" | "defaultValue"> &
  Omit<UseControllerProps, "defaultValue"> & {
  defaultValue?: any;
};

export function FormSelect({
  name,
  rules,
  shouldUnregister,
  defaultValue,
  control,
  disabled,
  ...props
}: FormSelectProps) {
  const { field, fieldState } = useController({
    name,
    rules,
    shouldUnregister,
    defaultValue,
    control,
    disabled,
  });

  const selectedOption = (props.options as any)?.find((opt: any) => opt.value === field.value) || null;

  return (
    <Select
      {...props}
      {...field}
      value={selectedOption as any}
      onChange={(option: any) => field.onChange(option?.value)}
      error={fieldState.error?.message}
    />
  );
}

export default FormSelect;

import { cn } from "@flaner/shared";
import { Loader2 } from "lucide-react";
import React, { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { IconTextField, IconTextFieldProps } from "../IconTextField";

export interface SearchBarProps<T> extends Omit<IconTextFieldProps, "onChange" | "results" | "onSelect" | "value"> {
  results?: T[];
  isLoading?: boolean;
  onSelect?: (item: T) => void;
  renderResult: (item: T) => React.ReactNode;
  keyExtractor?: (item: T) => string | number;
  emptyStateText?: string;
  onChange?: (value: string) => void;
  value?: string;
  hasMore?: boolean;
  onShowMore?: () => void;
  isFetchingNextPage?: boolean;
  showMoreText?: string;
}

export function SearchBar<T>({
  results = [],
  isLoading = false,
  onSelect,
  renderResult,
  keyExtractor = (item: any) => item.id || String(item),
  emptyStateText = "searchBar.emptySearch",
  onChange,
  value,
  className,
  onFocus,
  onKeyDown,
  alwaysOpen = false,
  hasMore,
  onShowMore,
  isFetchingNextPage,
  showMoreText = "searchBar.showMore",
  ...props
}: SearchBarProps<T>) {
  const { t } = useTranslation("common");

  const [isOpen, setIsOpen] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
     
    setSelectedIndex(-1);
  }, [results, value]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isOpen && e.key !== "Escape") {
      setIsOpen(true);
    }

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setSelectedIndex((prev) => (prev < results.length - 1 ? prev + 1 : prev));
        break;
      case "ArrowUp":
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : prev));
        break;
      case "Enter":
        e.preventDefault();
        if (selectedIndex >= 0 && selectedIndex < results.length) {
          onSelect?.(results[selectedIndex]);
          setIsOpen(false);
        } else if (selectedIndex === results.length && hasMore) {
          // If the "Show more" button is focused
          onShowMore?.();
        }
        break;
      case "Escape":
        e.preventDefault();
        setIsOpen(false);
        break;
    }

    onKeyDown?.(e);
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    setIsOpen(true);
    onFocus?.(e);
  };

  const handleClose = () => {
    setIsOpen(false);
    props.onClose?.();
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange?.(e.target.value);
    setIsOpen(true);
  };

  // Scroll into view on keyboard navigation
  useEffect(() => {
    if (selectedIndex >= 0 && listRef.current) {
      const selectedEl = listRef.current.children[selectedIndex] as HTMLElement;
      if (selectedEl) {
        selectedEl.scrollIntoView({ block: "nearest" });
      }
    }
  }, [selectedIndex]);

  const hasContent = Boolean(value && value.length > 0);
  const showDropdown = isOpen && hasContent;

  return (
    <div ref={containerRef} className={cn("relative z-50", alwaysOpen ? "w-full" : "w-fit", className)}>
      <IconTextField
        value={value}
        onChange={handleChange as any}
        onFocus={handleFocus}
        onKeyDown={handleKeyDown}
        alwaysOpen={alwaysOpen}
        {...props}
        onClose={handleClose}
      />

      <div
        className={cn(
          "absolute left-0 top-[calc(100%+0.5rem)] min-w-[20rem] md:min-w-[24rem] max-w-[calc(100vw-2rem)] overflow-hidden rounded-xl border border-border bg-popover shadow-lg transition-all duration-300 ease-[cubic-bezier(0.16,1,0.3,1)]",
          showDropdown
            ? "translate-y-0 opacity-100 pointer-events-auto"
            : "-translate-y-2 opacity-0 pointer-events-none",
        )}
      >
        {isLoading && results.length === 0 ? (
          <div className="flex items-center justify-center py-6 text-muted-foreground">
            <Loader2 className="size-6 animate-spin text-brand" />
          </div>
        ) : results.length > 0 ? (
          <ul ref={listRef} className={cn("max-h-80 overflow-y-auto py-2 outline-none transition-opacity duration-200", isLoading ? "opacity-50 pointer-events-none" : "opacity-100")}>
            {results.map((item, index) => {
              const isSelected = index === selectedIndex;
              return (
                <li
                  key={keyExtractor(item)}
                  onClick={() => {
                    onSelect?.(item);
                    setIsOpen(false);
                  }}
                  className={cn(
                    "cursor-pointer px-4 py-2.5 transition-colors",
                    isSelected ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
                  )}
                >
                  {renderResult(item)}
                </li>
              );
            })}

            {hasMore && (
              <li
                onClick={(e) => {
                  e.stopPropagation();
                  onShowMore?.();
                }}
                className={cn(
                  "cursor-pointer px-4 py-3 text-center text-sm font-medium text-brand transition-colors",
                  selectedIndex === results.length ? "bg-accent text-brand" : "hover:bg-accent/50",
                )}
              >
                {isFetchingNextPage ? <Loader2 className="size-4 animate-spin mx-auto" /> : t(showMoreText)}
              </li>
            )}
          </ul>
        ) : hasContent ? (
          <div className="py-6 text-center text-sm text-muted-foreground">{t(emptyStateText)}</div>
        ) : null}
      </div>
    </div>
  );
}

import { useId } from 'react';
import ReactSelect, { Props as SelectProps } from 'react-select';
import { clsx } from 'clsx';
import { Field, FieldLabel, FieldDescription, FieldError } from './ui/field';

export type SelectOption = {
  label: string;
  value: string;
}

export type CustomSelectProps = Omit<SelectProps<SelectOption, false>, 'size'> & {
  label?: string;
  description?: string;
  error?: string;
  containerClassName?: string;
  labelClassName?: string;
  disabled?: boolean;
}

export const Select = ({
  label,
  description,
  error,
  disabled = false,
  containerClassName,
  labelClassName,
  options,
  placeholder,
  value,
  onChange,
  id: customId,
  ...props
}: CustomSelectProps) => {
  const defaultId = useId();
  const selectId = customId || defaultId;

  const customClassNames = {
    control: ({ isFocused }: { isFocused: boolean }) =>
      clsx(
        "rounded-lg border bg-background transition-all duration-200 min-h-[40px] text-sm cursor-pointer",
        error
          ? "border-destructive focus-visible:ring-destructive"
          : isFocused
          ? "border-ring ring-1 ring-ring"
          : "border-input hover:border-accent"
      ),
    valueContainer: () => "px-3 py-1.5 flex items-center gap-1",
    singleValue: () => "text-foreground",
    placeholder: () => "text-muted-foreground",
    input: () => "text-foreground m-0 p-0",
    menu: () => "rounded-lg border border-border bg-popover shadow-lg mt-1.5 overflow-hidden z-50",
    menuList: () => "py-1 max-h-60 overflow-y-auto m-scroll",
    option: ({ isFocused, isSelected }: { isFocused: boolean; isSelected: boolean }) =>
      clsx(
        "px-3 py-2 text-sm cursor-pointer transition-colors duration-150",
        isSelected
          ? "bg-brand text-zinc-950 font-semibold"
          : isFocused
          ? "bg-accent text-accent-foreground"
          : "text-foreground/80 hover:text-foreground"
      ),
    indicatorsContainer: () => "px-2 gap-1",
    dropdownIndicator: () => "text-muted-foreground hover:text-foreground",
    clearIndicator: () => "text-muted-foreground hover:text-foreground",
    noOptionsMessage: () => "text-muted-foreground py-3 text-center text-sm",
  };

  return (
    <Field data-invalid={!!error} className={containerClassName}>
      {label && (
        <FieldLabel htmlFor={selectId} className={labelClassName}>
          {label}
        </FieldLabel>
      )}
      <div className="relative w-full">
        <ReactSelect
          id={selectId}
          options={options}
          value={value}
          onChange={onChange}
          isDisabled={disabled}
          placeholder={placeholder}
          unstyled
          classNames={customClassNames as any}
          {...props}
        />
      </div>
      {description && <FieldDescription>{description}</FieldDescription>}
      {error && <FieldError>{error}</FieldError>}
    </Field>
  );
};

Select.displayName = "Select";
export default Select;
